/bin/bash -lc "node - <<'NODE'
const base = 'https://dcc.ccdi.cancer.gov/api/v1/subject';
const perPage = 1000;
const diagnosisBySex = new Map();
const sexTotals = {F:0, M:0, U:0, Missing:0};
let totalParticipants = 0;
let participantsWithMissingDiagnosis = 0;
let diagnosisAssignments = 0;
let page = 1;
let allExpected = null;
const normalizeSex = (s) => (s === 'F' || s === 'M' || s === 'U') ? s : 'Missing';
const inc = (diagnosis, sex) => {
  if ("'!diagnosisBySex.has(diagnosis)) diagnosisBySex.set(diagnosis, {F:0, M:0, U:0, Missing:0, total:0});
  const row = diagnosisBySex.get(diagnosis);
  row[sex] += 1;
  row.total += 1;
};
while (true) {
  const params = new URLSearchParams({depositions:'"'phs002790', page:String(page), per_page:String(perPage)});
  const res = await fetch("'`${base}?${params}`);
  if (!res.ok) throw new Error(`HTTP ${res.status} page ${page}: ${await res.text()}`);
  const json = await res.json();
  if (json.errors) throw new Error(`API errors page ${page}: ${JSON.stringify(json.errors)}`);
  const data = json.data || [];
  if (allExpected == null) allExpected = json.summary?.counts?.all ?? null;
  for (const subj of data) {
    totalParticipants += 1;
    const sex = normalizeSex(subj.metadata?.sex?.value);
    sexTotals[sex] += 1;
    const diagnoses = subj.metadata?.associated_diagnoses;
    const vals = Array.isArray(diagnoses)
      ? [...new Set(diagnoses.map(d => d?.value).filter(v => typeof v === '"'string' && v.trim()).map(v => v.trim()))]
      : [];
    if (vals.length === 0) {
      participantsWithMissingDiagnosis += 1;
      inc('Missing diagnosis', sex);
    } else {
      for (const v of vals) {
        diagnosisAssignments += 1;
        inc(v, sex);
      }
    }
  }
  if (data.length < perPage) break;
  page += 1;
}
const rows = [...diagnosisBySex.entries()].map(([diagnosis, counts]) => ({diagnosis, ...counts}))
  .sort((a,b) => b.total - a.total || a.diagnosis.localeCompare(b.diagnosis));
console.log(JSON.stringify({
  endpoint: "'`${base}?depositions=phs002790&page=<1-${page}>&per_page=${perPage}`,
  pagesFetched: page,
  expectedParticipants: allExpected,
  totalParticipants,
  sexTotals,
  participantsWithMissingDiagnosis,
  diagnosisAssignmentsExcludingMissing: diagnosisAssignments,
  distinctDiagnosisRowsIncludingMissing: rows.length,
  topDiagnoses: rows.slice(0, 25),
}, null, 2));
NODE'

